    dp := make([][]int, n+1)
    for i := range dp {
        dp[i] = make([]int, 2)
    }

    for i := n - 1; i >= 0; i-- {
        for _, buying := range []bool{true, false} {
            buyIdx := 0
            if buying {
                buyIdx = 1
            }
            if buying {
                buy := -prices[i]
                if i+1 < n {
                    buy += dp[i+1][0]
                }
                cooldown := 0
                if i+1 < n {
                    cooldown = dp[i+1][1]
                }
                dp[i][1] = max(buy, cooldown)
            } else {
                sell := prices[i]
                if i+2 < n {
                    sell += dp[i+2][1]
                }
                cooldown := 0
                if i+1 < n {
                    cooldown = dp[i+1][0]
                }
                dp[i][0] = max(sell, cooldown)
            }
        }
    }

    return dp[0][1]
}

